function courseFromPrompt(prompt){const text=String(prompt||'').toLowerCase();if(/jupiter|jovian|ring plane|gas giant|magnetic shear/.test(text))return COURSES.find(c=>c.id==='jovian-shear');if(/earth|blue planet|low orbit|gravity pull|downward pull|downward gravity|gravity pulls? down/.test(text))return COURSES.find(c=>c.id==='earthfall-circuit');if(/ice|frost|titan|frozen|glacier|methane|arctic/.test(text))return COURSES.find(c=>c.id==='titan-veil');if(/lava|volcan|magma|fire|ash|eruption|io /.test(text))return COURSES.find(c=>c.id==='io-storm');if(/nebula|galaxy|cosmic|gravity|violet|spiral|deep space/.test(text))return COURSES.find(c=>c.id==='helix-deep');return COURSES[0]}
function coursePromptSeed(prompt){let hash=2166136261;for(const char of String(prompt||'')){hash^=char.charCodeAt(0);hash=Math.imul(hash,16777619)}return hash>>>0}
function updateCourseFromPrompt(){const prompt=$('world-prompt').value.trim();if(!prompt){toast('Describe a world to forge its course.');return}state.coursePrompt=prompt.slice(0,120);const course=courseFromPrompt(prompt);state.courseId=course.id;state.courseSeed=coursePromptSeed(state.coursePrompt);saveProfile();drawHome();renderRefinements();toast(`${course.name} route forged · add a detail to refine it`)}
