async function quickMatch(){if(quickMatch.busy)return;quickMatch.busy=true;state.playerName=getPilotName();try{const result=await api('quick',{name:state.playerName,ship:state.ship,botSkill:botSkillForRank(),difficulty:chosenDifficulty()});state.code=result.room.code;state.playerId=result.playerId;state.playerToken=result.token;state.host=!!result.host;state.botCount=result.room.bots;rememberSeat();roomView(result.room);showScreen('lobby-screen');startPolling();toast(result.host?'Quick match lobby open · anyone who presses QUICK MATCH lands here':'Joined a quick match lobby')}catch(e){toast(e.message)}finally{quickMatch.busy=false}}
async function createLobby(solo=false){state.playerName=getPilotName();state.host=true;state.playerId=null;state.code=null;state.botCount=solo?3:2;try{const result=await api('create',{name:state.playerName,bots:state.botCount,ship:state.ship,courseId:state.courseId,coursePrompt:state.coursePrompt,courseSeed:state.courseSeed||coursePromptSeed(state.coursePrompt||state.courseId),course:state.courseId.startsWith('forge-')?state.forgedCourse:null,botSkill:botSkillForRank(),difficulty:chosenDifficulty(),challengeId:solo?state.challenge?.id:undefined});state.code=result.room.code;state.playerId=result.playerId;state.playerToken=result.token;state.host=true;rememberSeat();roomView(result.room);if(solo){startPolling();showBriefing({onStart:()=>startMatch()});return}if(result.local)toast('Local preview lobby · published lobbies sync across devices');showScreen('lobby-screen');startPolling()}catch(e){toast(e.message)}}
async function joinLobby(){if(!state.joinRetries)state.joinCancelled=false;state.playerName=getPilotName();const code=$('join-code').value.trim().toUpperCase();if(code.length<4){toast('Enter the five-letter lobby code.');return}try{const result=await api('join',{code,name:state.playerName,ship:state.ship});if(state.joinCancelled){api('leave',{code,playerId:result.playerId,token:result.token}).catch(()=>{});return}state.code=code;state.playerId=result.playerId;state.playerToken=result.token;state.host=false;rememberSeat();state.playerName=result.room.players.find(p=>p.id===result.playerId)?.name||state.playerName;rememberSeat();state.courseId=result.room.courseId||state.courseId;state.coursePrompt=result.room.coursePrompt||'';hideJoinWait();state.joinRetries=0;roomView(result.room);showScreen('lobby-screen');toast('Joined the flight deck');startPolling()}catch(e){if(state.joinCancelled)return;/* Mid-heat: wait and join automatically as soon as the heat ends. */if(/in progress/i.test(e.message)&&(state.joinRetries=(state.joinRetries||0)+1)<=40){showJoinWait(code);clearTimeout(state.joinTimer);state.joinTimer=setTimeout(joinLobby,3000);return}hideJoinWait();state.joinRetries=0;toast(e.message)}}
// Pinned banner while a late joiner waits for the running heat to end.
function showJoinWait(code){let el=$('join-wait');if(!el){el=document.createElement('div');el.id='join-wait';el.className='join-wait';document.body.append(el)}if(!el.dataset.code||el.dataset.code!==code||el.hidden){el.dataset.code=code;el.innerHTML=`<b>⚔ JOINING ${escapeHtml(code)}</b><span>A heat is running · you're in as soon as it ends</span><div class="join-watch" id="join-watch"><small>LIVE NOW</small><em>Loading the race…</em></div><button type="button">CANCEL</button>`;el.querySelector('button').onclick=()=>{clearTimeout(state.joinTimer);state.joinRetries=0;state.joinCancelled=true;hideJoinWait()};clearInterval(showJoinWait.t);let tick=0;const watch=async()=>{/* Watch the running heat while you wait: live standings and the clock, from the room's public snapshot. */const box=$('join-watch');if(!box||el.hidden)return;if(tick++%3===0){try{const r=await fetch(`/.netlify/functions/game?code=${encodeURIComponent(code)}`);showJoinWait.data=r.ok?await r.json():null}catch{}}const d=showJoinWait.data,room=d?.room;if(!room)return;const left=Math.max(0,Math.ceil(((room.endsAt||0)-Date.now()-(state.serverOffset||0))/1000)),pilots=(d.live||[]).filter(e=>room.players.some(p=>p.id===e.id)).sort((a,b)=>b.score-a.score);box.innerHTML=`<small>LIVE NOW · HEAT ${room.heat} OF 3 · ${left>0?`0:${String(left).padStart(2,'0')} LEFT`:'FINISHING'}</small>${pilots.length?pilots.map((e,i)=>`<i><b>${i+1}</b> ${escapeHtml(String(e.name||'PILOT').toUpperCase())}<em>${Math.floor(e.score||0).toLocaleString()}</em></i>`).join(''):'<em>Pilots are on the grid…</em>'}${room.bots?`<i class="aliens">+ ${room.bots} alien rival${room.bots>1?'s':''}</i>`:''}`};watch();showJoinWait.t=setInterval(watch,1000)}el.hidden=false}
