let liveTimer=0;const rivalGhosts=new Map();
function stopLiveSync(){clearInterval(liveTimer);liveTimer=0;$('emote-bar').hidden=true;state.rivals={};for(const ghost of rivalGhosts.values()){world.remove(ghost);ghost.traverse(o=>{o.geometry?.dispose?.();o.material?.map?.dispose?.();o.material?.dispose?.()})}rivalGhosts.clear()}
// Stream our position and read the other human pilots' while a multiplayer heat runs.
function startLiveSync(room){stopLiveSync();if(!state.code||!(room?.players?.length>1))return;stealSeen={};emoteSeen=new Set();$('emote-bar').hidden=false;// One request in flight at a time, so slow responses can't stack up and land out of order.
const send=async()=>{const r=state.race;if(!r||(r.done&&Date.now()-(r.doneAt||0)>2500)||!state.code||send.busy)return;send.busy=true;try{const data=await api('live',{code:state.code,playerId:state.playerId,telemetry:{d:r.distance,x:r.x,y:r.y,score:projectedScore(r),rs:Math.floor(r.score),hull:r.hull,item:(r.rolling?r.pendingItem:r.item)||'',ammo:r.rolling?(ITEMS[r.pendingItem]?.ammo||1):(r.ammo||0),ba:getCombat().botAdjust(),lt:r.courseFinishTime??0},zaps:getCombat().outgoingZaps(),paid:getCombat().outgoingPaid(),fx:getCombat().outgoingFx(),drops:getCombat().outgoingDrops(),emote:takeEmote()});getCombat().receiveZaps(r,data.zapped);getCombat().receiveEffects(r,data.effects,state.serverOffset||0);getCombat().receiveDrops(data.drops);getCombat().receiveCredits(r,data.credits);receiveRoomFeed(data);const seen=new Set();for(const entry of data.live||[]){seen.add(entry.id);const prev=state.rivals[entry.id];/* Their own measured speed, for dead reckoning between updates. */const vel=prev&&entry.at>prev.at&&entry.d>=prev.d?THREE.MathUtils.clamp((entry.d-prev.d)/((entry.at-prev.at)/1000),8,50):prev?.vel;state.rivals[entry.id]={...entry,shown:prev?.shown??entry.d,stunUntil:prev?.stunUntil,receivedAt:Date.now(),vel}}for(const id of Object.keys(state.rivals))if(!seen.has(id)){/* Gone from the room (left or dropped): say so instead of vanishing. */if(r.started&&!r.done)showRaceToast(`${String(state.rivals[id].name||'A PILOT').toUpperCase()} DROPPED OUT`,'THE RACE GOES ON');delete state.rivals[id]}}catch{}finally{send.busy=false}};send();liveTimer=setInterval(send,450)}
function nameTag(text,color){const canvas=document.createElement('canvas');canvas.width=256;canvas.height=64;const ctx=canvas.getContext('2d');ctx.font='600 28px "DM Mono", monospace';ctx.textAlign='center';ctx.fillStyle='rgba(4,10,20,.72)';const w=Math.min(250,ctx.measureText(text).width+28);ctx.fillRect(128-w/2,10,w,44);ctx.fillStyle=color;ctx.fillRect(128-w/2,10,4,44);ctx.fillStyle='#f2f8ff';ctx.fillText(text,128,42);const texture=new THREE.CanvasTexture(canvas);texture.colorSpace=THREE.SRGBColorSpace;const sprite=new THREE.Sprite(new THREE.SpriteMaterial({map:texture,transparent:true,depthWrite:false,depthTest:false}));sprite.scale.set(3.2,.8,1);sprite.renderOrder=20;return sprite}
function rivalGhost(entry){let ghost=rivalGhosts.get(entry.id);if(ghost)return ghost;const colors=['#ff7ca7','#83c7ff','#ffd681','#c19aff','#70f5d9','#9dff7a'];const color=colors[rivalGhosts.size%colors.length];ghost=getCombat().makeRacerMesh({alien:alienFor(entry.name),color,label:String(entry.name||'PILOT').toUpperCase().slice(0,14),shipDef:SHIPS.find(x=>x.id===entry.ship)||SHIPS[0]}).ship;rivalGhosts.set(entry.id,ghost);return ghost}
function updateRivalGhosts(r,d){const seen=new Set();for(const rival of Object.values(state.rivals||{})){seen.add(rival.id);/* Keep predicting through a slow server response (up to 5 s) at the rival's own pace, then ease into the truth. */const age=Math.min(5,Math.max(0,(Date.now()+(state.serverOffset||0)-rival.at)/1000)),target=rival.d+age*(rival.vel||r.rate);rival.shown=THREE.MathUtils.lerp(rival.shown??target,target,Math.abs(target-(rival.shown??target))>30?.08:.18);const ghost=rivalGhost(rival),center=routeAt(rival.shown,r.route),gap=rival.shown-d;ghost.position.set(center.x+rival.x,center.y+rival.y,4.7-gap);ghost.visible=gap>-1.5&&gap<140&&!(gap<1.2&&Math.abs(rival.x-r.x)<2.2&&Math.abs(rival.y-r.y)<1.8);ghost.rotation.z=THREE.MathUtils.lerp(ghost.rotation.z,-(rival.x-(ghost.userData.lastX??rival.x))*2,.15);ghost.userData.lastX=rival.x}for(const [id,ghost] of rivalGhosts)if(!seen.has(id)){world.remove(ghost);rivalGhosts.delete(id)}}
// Lobby QR: a laptop player scans a phone straight into the room (same link as COPY INVITE LINK).
function renderInviteQr(room){const box=$('invite-qr'),code=$('invite-qr-code');if(!box||!code||!room?.code)return;/* A guest already on a phone doesn't need a code to scan: they share the link instead. */if(!state.host&&matchMedia('(pointer:coarse)').matches){box.hidden=true;return}if(code.dataset.room===room.code){box.hidden=false;return}try{const qr=qrcode(0,'M');qr.addData(inviteLink());qr.make();code.innerHTML=qr.createSvgTag({cellSize:4,margin:2,scalable:true});code.dataset.room=room.code;box.hidden=false}catch{box.hidden=true}}
function inviteLink(){return inviteLinkFor(state.code,state.playerName)}
async function shareInvite(){if(!state.code)return;const url=inviteLink(),text=`⚔ ${state.playerName} challenges you to a live battle race on ${courseInfo().name} in Starwake! Room ${state.code}`;try{if(navigator.share&&matchMedia('(pointer:coarse)').matches){await navigator.share({title:'Starwake',text,url});return}await navigator.clipboard.writeText(url);toast('Invite link copied · send it to your crew')}catch{let field=$('invite-link-field');if(!field){field=document.createElement('input');field.id='invite-link-field';field.className='challenge-link';field.readOnly=true;field.setAttribute('aria-label','Invite link');$('copy-code').closest('.lobby-heading')?.after(field)}field.value=url;field.focus();field.select();toast('Copy the invite link below and send it to your crew')}}
// Leaving the lobby or results screen also leaves the room on the server.
function exitRoom(){if(!state.code)return;clearInterval(pollTimer);stopLiveSync();const code=state.code,playerId=state.playerId;state.code=null;state.room=null;forgetSeat();api('leave',{code,playerId}).catch(()=>{})}
// A random id for this device's pilot: ladders follow it rather than the callsign.
function deviceId(){try{let d=localStorage.getItem('starwake-device');if(!/^[a-z0-9]{12,32}$/.test(d||'')){d=Array.from(crypto.getRandomValues(new Uint8Array(12)),b=>'abcdefghijklmnopqrstuvwxyz0123456789'[b%36]).join('');localStorage.setItem('starwake-device',d)}return d}catch{return undefined}}
const deviceHash=d=>[...String(d||'')].reduce((h,c)=>Math.imul(h^c.charCodeAt(0),16777619)>>>0,2166136261).toString(36);
// Seat resume: a reload (soft leave) keeps your seat for 30 s; this tab reclaims it on load.
function rememberSeat(){try{sessionStorage.setItem('starwake-seat',JSON.stringify({code:state.code,playerId:state.playerId,token:state.playerToken,name:state.playerName}))}catch{}}
function forgetSeat(){try{sessionStorage.removeItem('starwake-seat')}catch{}}
async function resumeSeat(){let seat=null;try{seat=JSON.parse(sessionStorage.getItem('starwake-seat')||'null')}catch{}if(!seat?.code||!seat.playerId)return false;state.code=seat.code;state.playerId=seat.playerId;state.playerToken=seat.token;state.playerName=seat.name||state.playerName;try{const {room,resume}=await api('resume',{code:seat.code,playerId:seat.playerId});state.room=room;state.host=room.hostId===state.playerId;roomView(room);startPolling();if(room.phase==='race'){state.pendingResume=resume||null;const restored=!!resume?.me;startRace(room);toast(restored?'Back in the battle · progress restored':'Back in the battle')}else if(room.players.length===1&&room.phase!=='lobby'){/* A solo heat that ended while reloading can't be shown again: start fresh. */exitRoom();showScreen('home-screen');toast('Your solo heat finished · start a new race')}else{showScreen('lobby-screen');toast(room.phase==='lobby'?'Back in the lobby':'Back in the room · you fly from the next heat')}return true}catch{state.code=null;state.playerId=null;state.playerToken=null;forgetSeat();toast('Your seat in that battle expired · ask for a fresh invite');return false}}
