function remixFor(prompt){const t=prompt.toLowerCase();return /lava|volcan|fire|magma|hot/.test(t)?'io-storm':/ice|crystal|snow|frozen|cold/.test(t)?'titan-veil':/earth|ocean|sea|planet|orbit/.test(t)?'earthfall-circuit':/jupiter|gas|ring|storm|wind/.test(t)?'jovian-shear':/nebula|ghost|haunt|purple|dream|disco/.test(t)?'helix-deep':'neon-rift'}
async function fuseParty(){if(fuseParty.busy||!state.host||!state.code)return;const ideas=partyIdeas();if(ideas.length<2)return;let prompt=`One racing world that fuses ${ideas.map(i=>i.idea).join(' + ')}`;if(prompt.length>180)prompt=prompt.slice(0,177)+'…';fuseParty.busy=true;renderParty(state.room);$('party-status').textContent='OpenAI is fusing your ideas into one world…';const seed=coursePromptSeed(prompt);let body;try{const r=await fetch('/.netlify/functions/forge',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt})});const data=await r.json().catch(()=>({}));const forged=r.ok&&normalizeCourseDefinition(data.course);if(!forged)throw new Error(data.error||'offline');/* AI unavailable, but the server offered a real earlier OpenAI world that matches the ideas */if(data.pooled){forged.summary=`Real OpenAI world, first forged from “${String(data.pooledPrompt||'').replace(/^One racing world that fuses /,'').slice(0,44)}”. ${forged.summary||''}`.slice(0,110);toast('AI busy · racing a real OpenAI world from an earlier fusion')}registerCourse(forged);state.forgedCourse=forged;body={course:forged,courseId:forged.id}}catch(err){/* AI offline: still a world made from the ideas — a fused name, a palette and a credit line on the closest built-in world. */const remix=partyRemix(prompt,ideas);if(remix){registerCourse(remix);state.forgedCourse=remix;body={course:remix,courseId:remix.id}}else body={courseId:remixFor(prompt)};toast('AI forge offline · remixed your ideas into a world')}try{const res=await api('course',{code:state.code,playerId:state.playerId,...body,coursePrompt:prompt,courseSeed:seed,partyBy:ideas.map(i=>i.who)});state.courseId=res.room.courseId;state.coursePrompt=prompt;state.courseSeed=seed;fuseParty.busy=false;roomView(res.room);sfx.perfect?.()}catch(err){fuseParty.busy=false;toast(err.message);renderParty(state.room)}}
