function burstSprite(){if(burstTexture)return burstTexture;const c=document.createElement('canvas');c.width=c.height=32;const g=c.getContext('2d'),grad=g.createRadialGradient(16,16,0,16,16,16);grad.addColorStop(0,'rgba(255,255,255,1)');grad.addColorStop(.4,'rgba(255,255,255,.5)');grad.addColorStop(1,'rgba(255,255,255,0)');g.fillStyle=grad;g.fillRect(0,0,32,32);burstTexture=new THREE.CanvasTexture(c);return burstTexture}
