function spawnBurst(color,x,y,count=20){if(!world||!state.race)return;const center=routeAt(state.race.distance,state.race.route),positions=new Float32Array(count*3),velocities=[];for(let i=0;i<count;i++){positions.set([center.x+x,center.y+y,4.7],i*3);const a=Math.random()*Math.PI*2,b=(Math.random()-.5)*Math.PI;velocities.push([Math.cos(a)*(2.5+Math.random()*3.5),Math.sin(a)*(2.5+Math.random()*3.5),-2-Math.random()*4])}const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.BufferAttribute(positions,3));const points=new THREE.Points(geometry,new THREE.PointsMaterial({color,size:.32,map:burstSprite(),transparent:true,opacity:1,depthWrite:false,blending:THREE.AdditiveBlending}));points.frustumCulled=false;world.add(points);bursts.push({points,velocities,born:performance.now()})}
function updateBursts(){const t=performance.now();for(const burst of [...bursts]){const age=(t-burst.born)/1000,attr=burst.points.geometry.attributes.position;if(age>.6){world.remove(burst.points);burst.points.geometry.dispose();burst.points.material.map=null;burst.points.material.dispose();bursts.splice(bursts.indexOf(burst),1);continue}for(let i=0;i<burst.velocities.length;i++){const v=burst.velocities[i];attr.setXYZ(i,attr.getX(i)+v[0]/60,attr.getY(i)+v[1]/60,attr.getZ(i)+v[2]/60)}attr.needsUpdate=true;burst.points.material.opacity=1-age/.6}}
