const soloHeat=()=>!(state.room?.players?.length>1);
function openRaceMenu(){if(!state.race||state.race.done||raceMenuOpen)return;raceMenuOpen=true;if(soloHeat()){state.race.pausedAt=serverClock();sfx.engine(0,false);$('race-menu').querySelector('strong').textContent='Paused';$('race-menu').querySelector('p').textContent='Solo heat paused. Take your time.'}else{$('race-menu').querySelector('strong').textContent='Heat in progress';$('race-menu').querySelector('p').textContent='The heat clock keeps running so every pilot stays in sync.'}Object.keys(keys).forEach(k=>keys[k]=false);$('race-menu').hidden=false;$('race-menu-resume').focus()}
function closeRaceMenu(){raceMenuOpen=false;const r=state.race;if(r?.pausedAt){const ms=Math.max(0,serverClock()-r.pausedAt);r.pausedAt=null;r.startsAt+=ms;r.endsAt+=ms;if(state.code)api('extend',{code:state.code,playerId:state.playerId,ms}).catch(()=>{})}const menu=$('race-menu');if(menu)menu.hidden=true}
function quitRace(){getCoach().reset();sfx.engine(0,false);closeRaceMenu();clearInterval(raceLoop);stopLiveSync();if(state.race)state.race.done=true;state.race=null;exitRoom();showScreen('home-screen')}
function resetRaceHud(r){$('score-label').textContent='0';$('combo-label').textContent='';$('star-count').textContent='00';$('race-progress').style.width='0%';$('checkpoint-label').textContent='LAP 01 · GATES 00 / 05';$('place-label').innerHTML='–';$('hull-meter').innerHTML='<i class="on"></i>'.repeat(5);$('fuel-meter').innerHTML='<i class="on"></i>'.repeat(5);const ticker=$('standings-ticker');if(ticker){ticker.hidden=true;ticker.innerHTML=''}$('app').classList.remove('star-burst','boosting','impact');clearRaceToasts()}
function projectedScore(r){return Math.floor(r.score+r.laps*300+Math.max(0,r.hull)*35*(r.time/r.duration))}
function updateStandingsTicker(r,elapsed){const box=$('standings-ticker');if(!box)return;const names=BOT_NAMES;const rows=[{id:'player',name:'YOU',d:projectedScore(r),me:true},...Object.values(state.rivals||{}).map(x=>({id:x.id,name:String(x.name||'PILOT').toUpperCase(),d:x.score||0,human:true})),...getCombat().botScores(r).map(b=>({id:b.id,name:b.name,d:b.score})),...getCombat().externalScores(r).map(b=>({id:b.id,name:b.name,d:b.score,human:true}))].sort((a,b)=>b.d-a.d);const meIndex=rows.findIndex(x=>x.me);const shown=rows.filter((x,i)=>i<4||x.me||x.human);const ti=teamInfo(),tOf=x=>ti?(x.me?ti.mine:ti.of(x.id)):null;box.innerHTML=shown.map(x=>{const place=rows.indexOf(x)+1,gap=Math.round(x.d-rows[meIndex].d),team=tOf(x);return `<div class="${x.me?'me':''}${x.human?' human':''}"><b>${place}</b><span>${team?`<i class="team-dot ${team}"></i>`:''}${x.id===getCombat().leader()?'♛ ':''}${x.id===r.nemesis?'<em class="nem">◎</em> ':''}${escapeHtml(x.name)}</span><i>${x.me?Math.floor(x.d).toLocaleString():(gap===0?'TIED':(Math.abs(gap)>=1000?(Math.abs(gap)/1000).toFixed(1)+'k':Math.abs(gap))+(gap>0?' AHEAD':' BEHIND'))}</i></div>`}).join('');box.hidden=false;box.classList.toggle('frenzy',getCombat().isFrenzy())}
function leaveRoom(){if(!state.code||!state.playerId)return;const payload=JSON.stringify({action:'leave',soft:true,code:state.code,playerId:state.playerId,token:state.playerToken});try{navigator.sendBeacon?.('/.netlify/functions/game',new Blob([payload],{type:'application/json'}))}catch{}}
