function startPolling(){clearInterval(pollTimer);pollTimer=setInterval(async()=>{if(!state.code)return;try{const r=await api('get',{code:state.code,method:'GET'});state.room=r.room;showScreenEmotes(r);/* Host can change hands (a silent host is replaced), so always take it from the room. */state.host=r.room.hostId===state.playerId;if(state.previousView==='lobby-screen')roomView(r.room);if(r.room.phase==='race'&&(state.previousView==='lobby-screen'||state.previousView==='results-screen')&&state.heat!==r.room.heat){if(r.room.heat===1)state.totalScore=0;state.heat=r.room.heat;startRace(r.room)}else if(r.room.phase==='race'&&state.previousView==='lobby-screen')startRace();if(state.previousView==='results-screen')updateResultGate(r.room);/* Only show results for a heat you actually flew; late joiners and reloaded pilots wait in the room. */if(r.room.phase==='results'&&state.previousView==='lobby-screen'&&state.race?.done)showResults(false);if(r.room.phase==='complete'&&state.previousView==='lobby-screen'&&state.race?.done)showResults(true);state.pollFailures=0}catch(e){state.pollFailures=(state.pollFailures||0)+1;if(/not found|no longer/i.test(e.message)||state.pollFailures>=8){clearInterval(pollTimer);stopLiveSync();const gone=/not found|no longer/i.test(e.message);state.code=null;toast(gone?'That room has closed. Back to the flight deck.':'Lost contact with flight control. Check your connection.');if(state.previousView!=='race-screen')showScreen('home-screen')}}},1200)}
