/* One request per press: Enter on a focused button used to send a second START (rejected with a toast). */async function startMatch(){if(startMatch.busy)return;startMatch.busy=true;try{const result=await api('start',{code:state.code,playerId:state.playerId});state.room=result.room;startRace(result.room)}catch(e){if(state.room?.phase!=='race')toast(e.message)}finally{startMatch.busy=false}}

