async function saveChallenge(){const r=state.race;if(!r?.run?.length){toast('Finish a heat first, then challenge a friend.');return null}const course=courseInfo();if(r.savedChallenge)return r.savedChallenge;const result=await api('challenge-save',{code:state.code,playerId:state.playerId,device:deviceId(),challenge:{roomHeat:state.heat,courseId:state.courseId,course:state.courseId.startsWith('forge-')?state.forgedCourse:null,coursePrompt:state.coursePrompt||'',courseSeed:Number(state.room?.courseSeed)||0,layoutCode:r.layout.code,heat:r.layout.heat,name:state.playerName,ship:state.ship,score:r.finalScore||0,duration:r.duration,run:r.run,parent:r.challenge?.id||null}});r.savedChallenge={id:result.id,course};rememberDare(result.id,course,r.finalScore||0);return r.savedChallenge}
// Dares you've sent, so the hub can show who replied (newest first, last 5).
function rememberDare(id,course,score){try{const list=JSON.parse(localStorage.getItem('starwake-sent-dares')||'[]').filter(d=>d.id!==id);list.unshift({id,course:course.name,score,name:state.playerName,at:Date.now()});localStorage.setItem('starwake-sent-dares',JSON.stringify(list.slice(0,5)))}catch{}}
async function sendChallenge(button){button.disabled=true;try{const saved=await saveChallenge();if(!saved)return;const score=Math.floor(state.race.finalScore).toLocaleString();const url=challengeLink(saved.id),how=await shareLink({url,text:`★ ${state.playerName} scored ${score} on ${saved.course.name} in Starwake. Think you can beat my run?`});if(how==='failed'){showShareField(url);toast('Copy the link below and send it to a friend')}else{toast(how==='copied'?'Challenge link copied · send it to a friend':'Challenge sent');button.querySelector('b').textContent='LINK COPIED ✓'}}catch(e){toast(e.message)}finally{button.disabled=false}}
